const upsertExercise = `-- name: UpsertExercise :exec
INSERT INTO exercises (id, user, updated_at, name, category_id, metadata_json, changed) VALUES (?, ?, ?, ?, ?, ?, unixepoch())
ON CONFLICT (user, id) DO UPDATE SET updated_at = excluded.updated_at, name = excluded.name, category_id = excluded.category_id, metadata_json = excluded.metadata_json, changed = excluded.changed
`

type UpsertExerciseParams struct {
	ID           string
	User         string
	UpdatedAt    time.Time
	Name         string
	CategoryID   sql.NullString
	MetadataJson []byte
}

func (q *Queries) UpsertExercise(ctx context.Context, arg UpsertExerciseParams) error {
	_, err := q.db.ExecContext(ctx, upsertExercise,
		arg.ID,
		arg.User,
		arg.UpdatedAt,
		arg.Name,
		arg.CategoryID,
		arg.MetadataJson,
	)
	return err
}

